const fs = require('fs');
const orig = fs.readFileSync('/trajectory.txt', 'utf8');

const hebrewText = "מצא את יחידת ספק הכוח הזולה ביותר עם תפוקת כוח של לפחות 600W.";
const englishText = "Find the cheapest power supply unit with a power output of at least 600W.";

const reconstructed = orig.replace(hebrewText, englishText);

fs.writeFileSync('/output/reconstruction.md', reconstructed, 'utf8');
console.log('Written reconstructed file successfully');

